<main class="page__body"><!--[--><!--[--><div class="hero hero--loaded" style="--bg-enter-delay:1.2s;"><div class="hero__bg"><img width="1920" height="1236" data-nuxt-img="" sizes="(max-width: 639px) 200vw, (max-width: 1279px) 100vw, (max-width: 1349px) 100vw, 1920px" srcset="/assets/img/fd4c7d265f48-veneers-hero-bg.avif 640w, /assets/img/d360331e564d-veneers-hero-bg.avif 1280w, /assets/img/ca7d9153e66e-veneers-hero-bg.avif 1920w, /assets/img/bb44c236b172-veneers-hero-bg.avif 2560w, /assets/img/0826524668da-veneers-hero-bg.avif 3840w" onerror="this.setAttribute('data-error', 1)" class="image image--loaded hero__image" alt="" fetchpriority="high" src="/assets/img/0826524668da-veneers-hero-bg.avif"></div><div class="hero__content"><div class="container container--size-default"><!--[--><div class="hero-content-grid"><div class="hero-content-grid__item hero-content-grid__item--header"><h1 class="hero__title u-text-headings-medium" style=""><span class="word" aria-hidden="true" style="display: inline-block;">Veneers</span><span class="sr-only" style="position: absolute; width: 1px; height: 1px; padding: 0px; margin: -1px; overflow: hidden; clip: rect(0px, 0px, 0px, 0px); white-space: nowrap; border: 0px;">Veneers</span></h1></div><div class="hero-content-grid__item hero-content-grid__item--body"><div class="video-dialog video-dialog--type-inline hero__video-preview"><video class="video-dialog__preview" width="250" height="445" muted="" loop="" playsinline="" src="/cms/api/media/file/veneers-hero-tease.webm" autoplay=""></video><button aria-label="Play video" class="video-dialog__button"><div class="icon-button icon-button--type-primary icon-button--size-medium video-dialog__play-button"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="54" height="54" viewBox="0 0 54 54"><path fill="currentColor" d="M22.031 19.687a1 1 0 0 1 1.515-.858l12.188 7.313a1 1 0 0 1 0 1.715L23.546 35.17a1 1 0 0 1-1.515-.857V19.687Z"></path></svg><!--]--></div><